/* The RVA Engine service worker (generated by build.py from src/site/sw.js).
   Precaches the app shell so the app opens offline. The cache name carries the build version, so every
   deploy installs a fresh cache; the page offers an "Update" button and the new worker takes over on tap. */
const VERSION = '1.0.0-5c257342f2';
const CACHE = 'rva-engine-' + VERSION;
const FILES = [
 "./",
 "index.html",
 "app.html",
 "site.css",
 "vendor/three-0.149.0.min.js",
 "manifest.webmanifest",
 "favicon.ico",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/maskable-192.png",
 "icons/maskable-512.png",
 "icons/apple-touch-icon.png",
 "img/skyline-night-800.webp",
 "img/skyline-night-1600.webp"
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))));
  // first install takes over at once; updates wait for the page's "Update" tap (see SW_REG_JS in build.py)
  if (!self.registration.active) self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('rva-engine-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', e => { if (e.data === 'skipWaiting') self.skipWaiting(); });

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;            // CDN fallback and anything external: browser default
  if (url.pathname.endsWith('.exe')) return;            // big downloads are never cached
  if (req.mode === 'navigate') {
    // pages: network first so a fresh deploy shows up, cached copy when offline or slow (4 s)
    e.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(req, { ignoreSearch: true }) || await cache.match(url.pathname.endsWith('/') ? './' : 'app.html');
      try {
        const net = fetch(req);
        const res = cached ? await Promise.race([net, new Promise((_, no) => setTimeout(no, 4000))]) : await net;
        if (res && res.ok && FILES.some(f => url.pathname.endsWith(f.replace('./', '/')))) cache.put(req, res.clone());
        return res;
      } catch (err) {
        if (cached) return cached;
        throw err;
      }
    })());
    return;
  }
  // static assets: cache first (they are versioned with the cache), then network
  e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req)));
});
